const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, PageBreak, Header, Footer, PageNumber, LevelFormat, BorderStyle, Table, TableRow, TableCell, WidthType, ShadingType, VerticalAlign } = require("docx");
const fs = require("fs");

// --- Helper Functions for Content Generation ---

function createHeading(text, level) {
    return new Paragraph({
        text: text,
        heading: level,
        spacing: { before: 240, after: 120 },
    });
}

function createText(text, options = {}) {
    return new Paragraph({
        children: [
            new TextRun({
                text: text,
                font: "SimSun", // Songti for body text
                size: 24, // 12pt
                ...options
            })
        ],
        spacing: { before: 120, after: 120 },
        alignment: AlignmentType.JUSTIFIED,
        indent: { firstLine: 480 } // 2 char indent
    });
}

function createBullet(text, level = 0) {
    return new Paragraph({
        children: [
            new TextRun({
                text: text,
                font: "SimSun",
                size: 24
            })
        ],
        numbering: {
            reference: "bullet-list",
            level: level
        },
        spacing: { before: 60, after: 60 }
    });
}

// --- Content Data (Synthesized & Expanded) ---

const titleText = "秒懂金融深度研究报告";
const subTitleText = "基于IP生态、内容方法论与市场影响力的全景分析";
const authorText = "分析师：幽浮喵 (AI Assistant)";
const dateText = "日期：2026年1月8日";

const executiveSummary = [
    "在当今中国金融市场日益成熟、个人财富管理需求爆发式增长的背景下，金融知识普及（Financial Literacy）已成为连接专业金融市场与普通投资者的关键桥梁。然而，传统金融教育往往面临“高冷”、“晦涩”、“脱离实际”的痛点。在此背景下，“秒懂金融”作为一种新兴的金融科普IP，凭借其独特的“降维打击”式内容策略，迅速在社交媒体与出版界崛起。",
    "本报告旨在对“秒懂金融”这一现象级IP进行全方位的深度剖析。我们将从宏观市场背景出发，探讨其诞生的土壤；深入挖掘主理人陈材杰的跨界背景如何重塑金融表达；系统拆解《秒懂金融》一书的内容架构与核心方法论；并重点分析其在小红书等新媒体平台的传播策略与用户生态。最终，本报告将评估其对普通投资者、金融从业者乃至整个金融科普行业的深远影响与启示。",
    "研究发现，“秒懂金融”的成功并非偶然，而是精准击中了“知识焦虑”与“碎片化学习”时代的痛点。通过“极简主义”的解释框架、“用户本位”的情感连接以及“社交货币化”的传播机制，它成功将复杂的金融原理转化为大众可消费的智力产品。这不仅是一个成功的商业案例，更为金融普惠教育提供了一个可复制的范式。"
];

const ch1_background = [
    "第一章：宏观背景与市场痛点",
    "1.1 国民理财意识觉醒与知识供给错配",
    "随着中国经济的飞速发展，居民家庭财富迅速积累。根据相关数据统计，中国个人可投资资产规模已突破百万亿大关。从“存银行”到“买房”，再到如今的股票、基金、理财产品多元化配置，国民的理财需求呈现出前所未有的旺盛态势。然而，与之形成鲜明对比的是国民金融素养的相对滞后。大量新入场的投资者缺乏基本的风险识别能力与资产配置概念，往往成为市场波动的“韭菜”。",
    "与此同时，传统的投资者教育长期存在“供需错配”。学院派教材理论深奥，充满数学模型与专业术语，让普通人望而却步；而市场上的营销号内容又往往甚至误导性强，缺乏系统性与专业性。市场急需一种既具备专业底蕴，又能够“说人话”、接地气的优质金融科普内容。这是“秒懂金融”诞生的根本土壤。",
    "1.2 “知识付费”与“碎片化阅读”的双重驱动",
    "移动互联网时代的到来，彻底改变了人们获取信息的方式。短视频、图文笔记等碎片化内容成为主流。人们越来越难以静下心来阅读大部头著作，而是倾向于在通勤、排队等碎片时间获取知识。这种“快餐式”的学习习惯，虽然被诟病不够深刻，但却是一个不可逆转的趋势。",
    "在此背景下，“秒懂”不仅是一个口号，更是一种核心竞争力。谁能在最短的时间内、用最直观的方式讲清楚一个复杂概念，谁就能赢得用户的注意力。同时，知识付费行业的成熟，也让优质的科普内容具备了变现的可能，激励了更多专业人士投身于内容创作。“秒懂金融”正是顺应了这一趋势，将金融知识封装为高密度的“知识胶囊”，满足了现代人高效学习的需求。"
];

const ch2_creator = [
    "第二章：IP主理人画像：陈材杰的跨界思维",
    "2.1 “非典型”金融专家的成长路径",
    "“秒懂金融”的灵魂人物陈材杰，其个人履历本身就极具传奇色彩与启发性。他并非传统的金融科班出身，本科主修工科。这种理工科的背景，为他日后理解和解构金融世界提供了一种独特的逻辑视角。工科思维强调逻辑闭环、结构化拆解与底层原理，这使得他在面对复杂的金融现象时，往往能跳出文科视角的模糊描述，直击事物的本质。",
    "在决定转型金融后，他以零基础的身份，完成了跨省、跨校、跨专业的“三跨”考研，成功考入国内顶尖财经院校攻读投资学硕士。这段艰难的求学经历，让他切身体会到了“金融小白”入门时的迷茫与痛点。他深知哪些概念最难懂，哪些教材最晦涩，因此在日后的创作中，他始终能保持“同理心”，站在初学者的角度去设计内容，而不是居高临下地“掉书袋”。",
    "2.2 国家级智库背景的专业背书",
    "目前，陈材杰担任国家级智库的青年研究人员，从事金融领域的宏观研究与咨询。这一身份为“秒懂金融”IP 注入了强大的公信力与专业深度。与市面上许多“野路子”财经博主不同，他的内容背后有着严谨的学术训练与宏观视野支撑。他能够将政策解读、宏观经济趋势分析融入到具体的理财建议中，使内容不仅“懂得了”，而且“站得高”、“看得远”。",
    "智库工作要求研究者具备极强的信息搜集、分析与提炼能力，这直接反哺了他的内容创作。他善于从海量的数据与政策文件中提取核心逻辑，将其转化为普通人听得懂的语言。这种“降维打击”的能力，是“秒懂金融”能够在一众财经账号中脱颖而出的核心壁垒。"
];

const ch3_content = [
    "第三章：《秒懂金融》内容生态深度拆解",
    "3.1 结构化设计：常识与操作的双轮驱动",
    "《秒懂金融》一书在结构设计上极具匠心，分为上篇“常识篇”和下篇“操作篇”。这种分层设计完美契合了读者的认知规律：先建立世界观，再掌握方法论。",
    "“常识篇”聚焦于宏观视野与底层逻辑。它不教你具体的K线战法，而是教你理解货币的本质、经济周期的规律以及生活中无处不在的金融现象。例如，书中对M0、M1、M2的解读，不仅仅是定义的堆砌，而是结合了“水库”、“水管”等生动比喻，让读者深刻理解货币供应量如何影响手中的财富购买力。对于GDP、CPI、PPI等宏观指标的解读，也紧扣“与我何干”这一核心命题，让宏观数据与个人生活建立连接。",
    "“操作篇”则通过“漏斗式”的逻辑，带领读者进入实战领域。从投资理财的底层思维（如复利、资产配置）入手，逐步深入到股票、基金等具体品种的实操。这一部分并非简单的“致富经”，而是侧重于建立科学的投资体系，强调纪律与心态的重要性。",
    "3.2 核心概念重塑：从“晦涩”到“通透”",
    "书中对金融核心概念的重塑是其最大亮点。例如，关于“风险”，传统教科书可能会列出方差、标准差等数学公式。而陈材杰则引用了著名的“鳄鱼法则”：当你被鳄鱼咬住脚时，如果你试图用手去挣脱，鳄鱼会同时咬住你的手脚；唯一的办法是牺牲那只脚。这个残酷而生动的比喻，瞬间让读者明白了“止损”的极端重要性——在金融市场中，保住本金永远是第一位的，少输比赢更重要。",
    "再如对“银行”的解读，他将其比喻为资金的“搬运工”和“中介”，剥离了银行高大上的外衣，直指其赚取存贷利差的商业本质。这种直击本质的解释方式，极大地降低了读者的认知负荷。",
    "3.3 “最少必要知识”原则",
    "在信息爆炸的时代，做减法比做加法更难。《秒懂金融》严格遵循“最少必要知识”（Minimum Viable Knowledge）原则。它不追求大而全的百科全书式罗列，而是精选了对普通人生活和投资影响最大的几十个核心概念。这种筛选本身就是一种高价值的服务。它告诉读者：你不需要成为金融博士，只需要掌握这20%的核心逻辑，就能解决生活中80%的金融问题。这种“极简主义”的内容哲学，极大地缓解了读者的学习焦虑。"
];

const ch4_methodology = [
    "第四章：“秒懂”背后的方法论：降维与重构",
    "4.1 隐喻与类比：认知桥梁的构建",
    "认知心理学认为，人类理解新事物最有效的方式是将其关联到已知的旧事物上。“秒懂金融”最核心的武器就是高超的隐喻（Metaphor）与类比（Analogy）技巧。书中几乎每一个抽象概念背后，都有一个来源于生活的生动场景。",
    "例如，在解释“通货膨胀”时，他可能会描述一个“奶茶涨价”的故事，而不是直接抛出CPI数据。在解释“复利”时，他会引用“滚雪球”的经典意象，并详细拆解雪球（本金）、坡度（收益率）与坡长（时间）三要素的关系。这些类比不仅准确，而且具有很强的画面感，能够让读者在脑海中瞬间建立起概念模型，从而实现“秒懂”。",
    "4.2 场景化叙事：从“定义”到“意义”",
    "传统的金融教育往往始于定义，终于公式。而陈材杰的叙事逻辑是：场景 -> 痛点 -> 概念 -> 解决方案。他总是先抛出一个生活中的常见困惑，比如“为什么工资涨了却感觉更穷了？”、“为什么买了基金总是亏钱？”，然后引出背后的金融原理（如实际购买力下降、追涨杀跌的心理陷阱），最后给出应对策略。这种“问题导向”的叙事方式，极大地增强了内容的代入感与实用性。读者阅读的不再是枯燥的条文，而是解决自己切身利益问题的说明书。",
    "4.3 视觉化思维与结构化表达",
    "作为工科背景的作者，陈材杰非常擅长使用图表、思维导图和结构化列表来辅助表达。在《秒懂金融》中，复杂的逻辑关系往往被梳理成清晰的流程图或对比表。这种视觉化的呈现方式，充分利用了人脑对图形处理的高效性，进一步降低了阅读门槛。他的文字也具有很强的结构感，喜欢用“第一、第二、第三”或“三个锦囊”、“四个原则”等形式进行归纳，便于读者记忆与复述。"
];

const ch5_strategy = [
    "第五章：数字传播战略：小红书生态下的IP爆发",
    "5.1 平台选择的精准性：为何是小红书？",
    "“秒懂金融”在小红书的爆发绝非偶然。小红书的用户群体以年轻、高知、女性用户为主，这一群体具有极强的自我提升意愿和消费能力，同时也是理财知识的“饥渴人群”。相比于抖音的极度娱乐化和知乎的过度硬核化，小红书“精致实用主义”的社区氛围与“秒懂金融”的气质高度契合。在这里，用户追求的是“有用”、“好看”且“能提升生活品质”的内容，而理财恰恰是提升生活掌控感的重要手段。",
    "5.2 “爆款笔记”的算法解码",
    "陈材杰深谙小红书的推荐算法机制。他的笔记往往具有极强的“封面党”与“标题党”属性，但这种吸引眼球并非通过低俗夸张，而是通过直击痛点的文案（如“小白必看”、“攒钱攻略”、“避坑指南”）和高颜值的排版来实现。他善于利用“情绪价值”，将理财与“独立女性”、“搞钱思维”、“早日退休”等热门话题挂钩，激发用户的点击与收藏欲望。",
    "数据表明，小红书的算法极其看重“收藏率”。“秒懂金融”的内容多为干货合集或知识图谱，具有很强的“工具书”属性，用户往往会选择“先马后看”。这种高收藏率迅速推高了笔记的权重，使其进入更大的流量池，从而形成正向循环。",
    "5.3 社交货币与社区共创",
    "在社交媒体时代，内容即社交货币。“秒懂金融”的内容往往设计得非常易于分享。当用户转发一篇关于“如何看懂美林时钟”的笔记时，不仅仅是在分享知识，更是在展示自己“懂理财”、“有规划”的积极人设。这种社交属性极大地促进了内容的病毒式传播。",
    "此外，陈材杰非常注重与粉丝的互动。通过评论区的答疑解惑，他不仅增强了用户粘性，还能敏锐地捕捉到大众最新的理财困惑，从而反向定制下一阶段的选题。这种“C2B”（Consumer to Business）的内容生产模式，保证了他的输出永远紧跟市场需求。"
];

const ch6_conclusion = [
    "第六章：总结与展望：金融科普的未来",
    "6.1 对普通投资者的价值重估",
    "“秒懂金融”的最大价值，在于它打破了金融知识的阶层壁垒，实现了某种程度上的“认知平权”。它告诉普通人：金融不是华尔街精英的专属游戏，而是每个人守护劳动成果、规划美好生活的必备技能。通过掌握基础的金融常识，普通人或许无法一夜暴富，但至少可以避免被通胀悄悄收割，避免落入庞氏骗局的陷阱，建立起一种从容理性的财富观。",
    "6.2 对金融行业的启示",
    "对于金融机构和从业者而言，“秒懂金融”提供了一个极佳的用户沟通范本。在过去，金融机构往往高高在上，导致与客户之间存在巨大的信任鸿沟。陈材杰的成功证明，真诚、平视、说人话的沟通方式，才是赢得客户信任的王道。未来的金融服务，必然是“产品+内容”的复合体，谁能做好投资者教育，谁就能占据用户的心智高地。",
    "6.3 局限性与未来挑战",
    "当然，我们也要清醒地看到“秒懂”模式的局限性。金融市场的复杂性决定了某些深层逻辑是无法完全被“简化”的。过度的简化可能会导致“幸存者偏差”或对风险的低估。读者在享受“秒懂”快感的同时，也需要警惕“懂了皮毛就以为懂了全部”的自大心理。未来的“秒懂金融”，需要在“通俗性”与“严谨性”之间寻找更微妙的平衡，引导读者从“秒懂”走向“深思”，从“入门”走向“精通”。",
    "综上所述，“秒懂金融”不仅是一本书、一个账号，更代表了金融认知进化的一种方向。在这个充满不确定性的时代，它为无数普通人点亮了一盏看清财富迷雾的明灯。"
];

